// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/admin/v1/admissions", wrapper.ListAdmissions)
	router.POST(options.BaseURL+"/admin/v1/admissions", wrapper.CreateAdmission)
	router.DELETE(options.BaseURL+"/admin/v1/admissions/:ref", wrapper.RevokeAdmission)
	router.GET(options.BaseURL+"/admin/v1/audit-logs", wrapper.ListAuditLogs)
	router.POST(options.BaseURL+"/admin/v1/auth/login", wrapper.AdminLogin)
	router.POST(options.BaseURL+"/admin/v1/auth/logout", wrapper.AdminLogout)
	router.GET(options.BaseURL+"/admin/v1/metrics", wrapper.GetMetrics)
	router.GET(options.BaseURL+"/admin/v1/models", wrapper.ListModels)
	router.POST(options.BaseURL+"/admin/v1/models", wrapper.CreateModel)
	router.PATCH(options.BaseURL+"/admin/v1/models/:id", wrapper.UpdateModel)
	router.POST(options.BaseURL+"/admin/v1/models/:id/test", wrapper.TestModel)
	router.GET(options.BaseURL+"/admin/v1/prompt-releases", wrapper.ListPromptReleases)
	router.PUT(options.BaseURL+"/admin/v1/prompt-releases", wrapper.SetPromptRelease)
	router.GET(options.BaseURL+"/admin/v1/prompt-versions", wrapper.ListPromptVersions)
	router.POST(options.BaseURL+"/admin/v1/prompt-versions", wrapper.CreatePromptVersion)
	router.GET(options.BaseURL+"/admin/v1/routes", wrapper.ListRoutes)
	router.PUT(options.BaseURL+"/admin/v1/routes/:task", wrapper.SetRoute)
}
